import { test, expect } from '@playwright/test';

test.describe('Payment Timeout Redirect to Error Page', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/payment');
  });

  test('should redirect to error page when payment times out', async ({ page }) => {
    // Setup: intercept the payment API call and simulate timeout
    await page.route('**/api/payment', (route) => {
      route.abort('Payment timeout');
    });

    // Intercept the success route and redirect to error page
    await page.route('**/api/payment/success', (route) => {
      route.abort('Payment success');
    });

    // Intercept the failure route and redirect to error page
    await page.route('**/api/payment/failure', (route) => {
      route.abort('Payment failure');
    });

    // Verify error page is visible
    const errorPage = page.getByRole('region', { name: /error/i });
    await expect(errorPage).toBeVisible();

    // Verify error message is displayed
    const errorMessage = page.getByText(/payment failed/i);
    await expect(errorMessage).toBeVisible();

    // Verify error page has correct title
    const errorPageTitle = page.getByText(/error/i);
    await expect(errorPageTitle).toBeVisible();

    // Verify back button is available
    const backButton = page.getByRole('button', { name: /back/i });
    await expect(backButton).toBeVisible();

    // Verify payment form is still visible
    const paymentForm = page.getByRole('form', { name: /payment form/i });
    await expect(paymentForm).toBeVisible();

    // Verify payment details are still visible
    const paymentDetails = page.getByText(/amount: $100/i);
    await expect(paymentDetails).toBeVisible();

    // Verify error page has correct status code
    const status = page.getByRole('status');
    await expect(status).toHaveTextContent('Error');
  });

  test('should handle successful payment and display success page', async ({ page }) => {
    // Setup: intercept the payment API call and simulate success
    await page.route('**/api/payment', (route) => {
      route.continue();
    });

    // Intercept the success route and redirect to success page
    await page.route('**/api/payment/success', (route) => {
      route.continue();
    });

    // Intercept the failure route and redirect to error page
    await page.route('**/api/payment/failure', (route) => {
      route.abort('Payment failure');
    });

    // Verify success page is visible
    const successPage = page.getByRole('region', { name: /success/i });
    await expect(successPage).toBeVisible();

    // Verify success message is displayed
    const successMessage = page.getByText(/payment successful/i);
    await expect(successMessage).toBeVisible();

    // Verify success page has correct title
    const successPageTitle = page.getByText(/success/i);
    await expect(successPageTitle).toBeVisible();

    // Verify payment details are displayed
    const paymentDetails = page.getByText(/amount: $100/i);
    await expect(paymentDetails).toBeVisible();

    // Verify success button is available
    const successButton = page.getByRole('button', { name: /confirm/i });
    await expect(successButton).toBeVisible();

    // Verify success page has correct status code
    const status = page.getByRole('status');
    await expect(status).toHaveTextContent('Success');
  });
});
